"""Generate LFS attributes while preserving imported text bytes. Python 3.9+."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
EXTENSIONS = ('png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'tga', 'tif', 'tiff',
              'psd', 'psb', 'ora', 'aseprite', 'ase', 'wav', 'ogg', 'mp3', 'flac', 'opus',
              'ttf', 'otf', 'mp4', 'webm', 'mov', 'zip', 'unitypackage', 'bytes')


def expected_attributes():
    lines = [
        '# Generated by python tools/configure_lfs.py --write.',
        '# Preserve imported source bytes, including original CRLF and metadata.',
        '* -text',
        '/README.md text eol=lf',
        '/.gitattributes text eol=lf',
        '/.gitignore text eol=lf',
        '/catalog.json text eol=lf',
        '/generated-assets.json text eol=lf',
        '/.lfs-payloads.json text eol=lf',
        '**/asset.json text eol=lf',
        '/tools/*.py text eol=lf',
        # Authored UI source documents preserve their original CRLF bytes.
        '/ui/combat-hud-approved-20261106/** whitespace=cr-at-eol',
        '/ui/combat-hud-rebuilt-20261106/** whitespace=cr-at-eol',
        '/ui/combat-hud-expanded-20261106/** whitespace=cr-at-eol',
        '/ui/inventory-symbols-20261106/** whitespace=cr-at-eol',
        '/monsters/stage-01/bosses/clock-executioner/source/battle-preview/asset-manifest.json -text whitespace=cr-at-eol',
        '/monsters/stage-01/normal/barrel-gunner/source/** -text whitespace=cr-at-eol',
        '/monsters/stage-01/normal/millstone-charger/source/** -text whitespace=cr-at-eol',
        '/monsters/stage-02/elite/stone-fist/source/** -text whitespace=cr-at-eol',
        '/monsters/stage-02/elite-boss-pattern-drafts/source/** -text whitespace=cr-at-eol',
        '/ui/inventory-journal-kit/runtime/layout.json -text whitespace=cr-at-eol',
        '/ui/inventory-journal-kit/source/** -text whitespace=cr-at-eol',
        '/ui/inventory-journal-concept/source/** -text whitespace=cr-at-eol',
        '/ui/inventory-journal-concept/source/prompt.txt -text whitespace=cr-at-eol,-blank-at-eol',
        '/environments/stage1-actual-layered-bright-20261111/source/rooms.json whitespace=cr-at-eol',
        '',
        '# Binary assets; match uppercase extensions too.',
    ]
    for extension in EXTENSIONS:
        pattern = '*.' + ''.join('[' + c.lower() + c.upper() + ']' for c in extension)
        lines.append(pattern + ' filter=lfs diff=lfs merge=lfs -text')
    lines.extend(['', '# Exact files containing embedded image/audio data.'])
    payloads = json.loads((ROOT / '.lfs-payloads.json').read_text(encoding='utf-8'))
    for name in sorted(payloads):
        quoted = '"' + name.replace('\\', '\\\\').replace('"', '\\"') + '"'
        lines.append(quoted + ' filter=lfs diff=lfs merge=lfs -text')
    return '\n'.join(lines) + '\n'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--write', action='store_true')
    args = parser.parse_args()
    path = ROOT / '.gitattributes'
    text = expected_attributes()
    if args.write:
        path.write_bytes(text.encode('utf-8'))
        print('Generated .gitattributes')
    else:
        if path.read_bytes() != text.encode('utf-8'):
            raise SystemExit('Attributes differ; run python tools/configure_lfs.py --write')
        print('PASS: LFS attributes match the binary and embedded payload rules')


if __name__ == '__main__':
    main()
